query ValidateDataIntegrity($options: ValidationOptions) {
  validateDataIntegrity(options: $options) {
    isValid
    summary {
      totalChecks
      passedChecks
      failedChecks
      warningCount
    }
    issues {
      id
      type
      severity
      message
      affectedNodes {
        id
        table
        title
      }
      recommendation
      fixable
    }
    checks {
      orphanNodes {
        count
        samples {
          id
          table
          title
        }
      }
      duplicateData {
        count
        duplicateGroups {
          hash
          nodes {
            id
            title
          }
        }
      }
      schemaViolations {
        count
        violations {
          rule
          affectedCount
          samples
        }
      }
      brokenRelations {
        count
        samples {
          fromNode
          toNode
          relationType
        }
      }
    }
  }
}
